using UnityEngine;
using UnityEngine.Events;

public class Puerta : MonoBehaviour
{
    // Aparece en el Inspector para wiring visual
    public UnityEvent OnAbrirse;
    public UnityEvent OnCerrarse;

    bool abierta = false;

    public void Activar()
    {
        abierta = !abierta;
        if (abierta)
            OnAbrirse.Invoke();   // llama a todos los listeners del Inspector y código
        else
            OnCerrarse.Invoke();
    }
}

// Suscripción por código (equivalente a += en C# events)
public class SistemaSonido : MonoBehaviour
{
    [SerializeField] Puerta puerta;

    void OnEnable()
    {
        puerta.OnAbrirse.AddListener(ReproducirSonidoAbrir);
        puerta.OnCerrarse.AddListener(ReproducirSonidoCerrar);
    }

    void OnDisable()
    {
        puerta.OnAbrirse.RemoveListener(ReproducirSonidoAbrir);
        puerta.OnCerrarse.RemoveListener(ReproducirSonidoCerrar);
    }

    void ReproducirSonidoAbrir()  => Debug.Log("Sonido: puerta abre");
    void ReproducirSonidoCerrar() => Debug.Log("Sonido: puerta cierra");
}

using UnityEngine;
using UnityEngine.UI;

public class MenuManager : MonoBehaviour
{
    [SerializeField] Button btnJugar;
    [SerializeField] Button btnOpciones;
    [SerializeField] Button btnSalir;

    void OnEnable()
    {
        // AddListener en lugar de += para UnityEvent
        btnJugar.onClick.AddListener(IniciarJuego);
        btnOpciones.onClick.AddListener(AbrirOpciones);
        btnSalir.onClick.AddListener(SalirJuego);
    }

    void OnDisable()
    {
        btnJugar.onClick.RemoveListener(IniciarJuego);
        btnOpciones.onClick.RemoveListener(AbrirOpciones);
        btnSalir.onClick.RemoveListener(SalirJuego);
    }

    void IniciarJuego()  => UnityEngine.SceneManagement.SceneManager.LoadScene("Nivel1");
    void AbrirOpciones() => Debug.Log("Abriendo opciones...");
    void SalirJuego()    => Application.Quit();
}

