using UnityEngine.Events;

[System.Serializable]
public class IntEvent : UnityEvent<int> { }

public class ScoreManager : MonoBehaviour
{
    public IntEvent OnScoreCambio;
    int score = 0;

    public void Puntuar(int pts)
    {
        score += pts;
        OnScoreCambio.Invoke(score);
    }
}

public class MainMenu : MonoBehaviour
{
    [SerializeField] Button btnJugar;
    [SerializeField] Button btnSalir;

    void Awake()
    {
        btnJugar.onClick.AddListener(() => SceneManager.LoadScene(1));
        btnSalir.onClick.AddListener(Application.Quit);
    }
}

